function blocked(hit){return !allowed()||document.hidden||document.documentElement.classList.contains('intro-open')||document.querySelector('dialog[open]')||!hit?.closest||hit.closest('input,textarea,select,option,[contenteditable],dialog');}
function context(hit){if(blocked(hit)){hide();return false;}let mode='default',text='';if(!hit.closest('button:disabled,[aria-disabled="true"]')){if(hit.closest('.pathway')){mode='explore';text='Explore';}else if(hit.closest('#book')){mode='drag';text='Drag';}else if(hit.closest('a[href],button')){mode='action';text='↗';}}cursor.dataset.mode=mode;label.textContent=text;cursor.classList.toggle('is-light',Boolean(hit.closest('#pathways')));return true;}
function request(){if(!frame)frame=requestAnimationFrame(render);}
