if(typeof MutationObserver!=='undefined'){const observer=new MutationObserver(()=>{if(document.documentElement.classList.contains('intro-open')||document.querySelector('dialog[open]'))hide();});observer.observe(document.documentElement,{attributes:true,attributeFilter:['class']});const dialog=document.getElementById('path-dialog');if(dialog)observer.observe(dialog,{attributes:true,attributeFilter:['open']});}
const art=document.querySelector('#initiatives .initiative-visual'),rows=[...document.querySelectorAll('#pathways .pathway')];function resetArt(){if(!art)return;art.style.setProperty('--surface-rx','0deg');art.style.setProperty('--surface-ry','0deg');art.style.setProperty('--surface-light','0');}if(art){art.addEventListener('pointermove',e=>{if(!allowed()||e.pointerType==='touch')return;const r=art.getBoundingClientRect(),px=clamp((e.clientX-r.left)/r.width,0,1),py=clamp((e.clientY-r.top)/r.height,0,1);art.style.setProperty('--surface-rx',`${((.5-py)*3).toFixed(2)}deg`);art.style.setProperty('--surface-ry',`${((px-.5)*4).toFixed(2)}deg`);art.style.setProperty('--surface-x',`${(px*100).toFixed(1)}%`);art.style.setProperty('--surface-y',`${(py*100).toFixed(1)}%`);art.style.setProperty('--surface-light','1');},{passive:true});art.addEventListener('pointerleave',resetArt);}
